//! `ImageryLayer` request creation, outcomes, per-server throttling and
//! cancellation against the pinned CesiumJS traces in
//! `tests/data/scene-imagery-requests.json` (generated by
//! `tools/cesium/generate-scene-imagery-requests.mjs`).
#![allow(clippy::arc_with_non_send_sync)] // Providers use single-threaded shared state.

use cesium_rs::core::image_helpers::ImageFuture;
use cesium_rs::core::*;
use cesium_rs::scene::imagery_provider::{
    ImageryErrorEvent, ImageryFuture, ImageryImage, ImageryProvider, ImageryRequest,
};
use cesium_rs::scene::*;
use serde_json::{json, Value};
use std::cell::{Cell, RefCell};
use std::rc::Rc;
use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::{Arc, Mutex};

fn fixture() -> Value {
    serde_json::from_str(include_str!("data/scene-imagery-requests.json")).unwrap()
}

fn state_name(state: ImageryState) -> &'static str {
    match state {
        ImageryState::Unloaded => "UNLOADED",
        ImageryState::Transitioning => "TRANSITIONING",
        ImageryState::Received => "RECEIVED",
        ImageryState::TextureLoaded => "TEXTURE_LOADED",
        ImageryState::Ready => "READY",
        ImageryState::Failed => "FAILED",
        ImageryState::Invalid => "INVALID",
        ImageryState::Placeholder => "PLACEHOLDER",
    }
}

fn request_state_name(state: RequestState) -> &'static str {
    match state {
        RequestState::Unissued => "UNISSUED",
        RequestState::Issued => "ISSUED",
        RequestState::Active => "ACTIVE",
        RequestState::Received => "RECEIVED",
        RequestState::Cancelled => "CANCELLED",
        RequestState::Failed => "FAILED",
    }
}

/// Plays one scripted outcome per attempt, as the generator's provider does.
struct ScriptedProvider {
    scheme: GeographicTilingScheme,
    error_event: ImageryErrorEvent,
    script: Vec<String>,
    attempt: Arc<AtomicUsize>,
    requests: RefCell<Vec<Value>>,
    credits_calls: Cell<usize>,
}

impl ImageryProvider for ScriptedProvider {
    fn rectangle(&self) -> &Rectangle {
        self.scheme.rectangle()
    }
    fn tile_width(&self) -> f64 {
        256.0
    }
    fn tile_height(&self) -> f64 {
        256.0
    }
    fn maximum_level(&self) -> Option<u32> {
        None
    }
    fn tiling_scheme(&self) -> &dyn TilingScheme {
        &self.scheme
    }
    fn error_event(&self) -> &ImageryErrorEvent {
        &self.error_event
    }
    fn get_tile_credits(&self, _: i32, _: i32, _: u32) -> Option<Vec<Credit>> {
        self.credits_calls.set(self.credits_calls.get() + 1);
        Some(vec![Credit::new("tile", false)])
    }
    fn request_image(&self, x: i32, y: i32, level: u32) -> Option<ImageryFuture> {
        self.request_image_with_request(x, y, level, None)
    }
    fn request_image_with_request(
        &self,
        _: i32,
        _: i32,
        _: u32,
        request: Option<ImageryRequest>,
    ) -> Option<ImageryFuture> {
        let request = request.expect("ImageryLayer passes a request");
        let attempt = self.attempt.fetch_add(1, Ordering::SeqCst);
        let outcome = self.script[attempt.min(self.script.len() - 1)].clone();
        {
            let r = request.borrow();
            self.requests.borrow_mut().push(json!({
                "throttle": r.options.throttle,
                "throttleByServer": r.options.throttle_by_server,
                "imagery": r.options.request_type == RequestType::Imagery,
                "state": request_state_name(r.state),
            }));
        }
        let image = || Ok(ImageryImage::Image(FrameResource::new(vec![0u8; 4])));
        match outcome.as_str() {
            "undefined" => None,
            "resolve" => Some(Box::pin(std::future::ready(image()))),
            "cancelReject" => {
                request.borrow_mut().state = RequestState::Cancelled;
                Some(Box::pin(std::future::ready(Err(RuntimeError::new("cancelled")))))
            }
            "reject" => Some(Box::pin(std::future::ready(Err(RuntimeError::new(format!("failed {}", attempt + 1)))))),
            other => panic!("unknown outcome {other}"),
        }
    }
}

#[test]
fn request_outcomes_match_reference() {
    let fixture = fixture();
    let mut checked = 0;
    for case in fixture["outcomes"].as_array().unwrap() {
        let script: Vec<String> =
            case["script"].as_array().unwrap().iter().map(|v| v.as_str().unwrap().into()).collect();
        if script.iter().any(|s| s == "resolveUndefined") {
            // Cesium treats a promise that resolves to undefined as a failure.
            // `ImageryFuture` resolves to an image or an error, so the port
            // cannot express it; the `reject` case covers the same path.
            continue;
        }
        let attempt = Arc::new(AtomicUsize::new(0));
        let provider = Arc::new(ScriptedProvider {
            scheme: GeographicTilingScheme::default(),
            error_event: Rc::new(RefCell::new(MutableErrorEvent::new())),
            script: script.clone(),
            attempt: attempt.clone(),
            requests: RefCell::new(Vec::new()),
            credits_calls: Cell::new(0),
        });
        let errors: Arc<Mutex<Vec<Value>>> = Arc::default();
        {
            let (errors, attempt, length) = (errors.clone(), attempt.clone(), script.len());
            provider.error_event.borrow_mut().add_event_listener(move |e| {
                errors.lock().unwrap().push(json!({
                    "message": e.message, "timesRetried": e.times_retried, "x": e.x, "y": e.y, "level": e.level,
                }));
                e.retry = attempt.load(Ordering::SeqCst) < length;
            });
        }
        let mut layer = ImageryLayer::new(Some(provider.clone()), ImageryLayerOptions::default());
        let imagery = layer.get_imagery_from_cache(1, 2, 3, None);
        layer.request_imagery(&imagery);
        let context = format!("{script:?}");
        {
            let i = imagery.borrow();
            let after = &case["afterCall"];
            assert_eq!(state_name(i.state), after["state"], "{context} after call");
            assert_eq!(json!(i.request.is_some()), after["hasRequest"], "{context} after call");
            assert_eq!(json!(i.credits.as_ref().map(Vec::len)), after["credits"], "{context} credits");
        }
        for _ in 0..5 {
            layer.poll_imagery(&imagery);
        }
        let i = imagery.borrow();
        let expected = &case["final"];
        assert_eq!(state_name(i.state), expected["state"], "{context} final");
        assert_eq!(json!(i.request.is_some()), expected["hasRequest"], "{context} final");
        assert_eq!(json!(i.image.is_some()), expected["hasImage"], "{context} final");
        assert_eq!(json!(provider.credits_calls.get()), case["creditsCalls"], "{context} credits calls");
        let requests: Vec<Value> = case["requests"]
            .as_array()
            .unwrap()
            .iter()
            .map(|r| {
                assert_eq!(r["type"], 1, "IMAGERY");
                json!({"throttle": r["throttle"], "throttleByServer": r["throttleByServer"], "imagery": true, "state": r["state"]})
            })
            .collect();
        assert_eq!(*provider.requests.borrow(), requests, "{context} requests");
        assert_eq!(*errors.lock().unwrap(), case["errors"].as_array().unwrap().clone(), "{context} errors");
        checked += 1;
    }
    assert_eq!(checked, 5);
}

// --- Per-server throttling through a real provider ---------------------------

/// Never answers, so requests stay active until they are cancelled.
struct SilentTransport;
impl ResourceTransport for SilentTransport {
    fn execute(&self, _: HttpRequest) -> RequestFuture<HttpResponse> {
        Box::pin(std::future::pending())
    }
}

struct Images;
impl ImageHost for Images {
    type Image = RgbaImage;
    fn dimensions(&self, image: &RgbaImage) -> (u32, u32) {
        (image.width, image.height)
    }
    fn image_from_rgba(&self, image: RgbaImage) -> Result<RgbaImage, RuntimeError> {
        Ok(image)
    }
    fn image_pixels(&self, image: &RgbaImage, _: u32, _: u32) -> Result<Vec<u8>, RuntimeError> {
        Ok(image.pixels.clone())
    }
    fn resize_image(&self, image: &RgbaImage, _: u32, _: u32) -> Result<RgbaImage, RuntimeError> {
        Ok(image.clone())
    }
    fn decode_image<'a>(
        &'a self,
        _: &'a [u8],
        _: &'a str,
        _: ImageDecodeOptions,
    ) -> Option<ImageFuture<'a, RgbaImage>> {
        None
    }
}

#[test]
fn per_server_throttling_and_cancellation_match_reference() {
    let fixture = fixture();
    let expected = &fixture["throttling"];
    let client = Rc::new(ResourceClient::new(Rc::new(SilentTransport)));
    assert_eq!(json!(client.scheduler.borrow().maximum_requests_per_server), expected["maximumRequestsPerServer"]);
    let provider = UrlTemplateImageryProvider::new(
        ImageryLoader::new(client.clone(), Rc::new(Images)),
        UrlTemplateImageryProviderOptions::new(Resource::new("https://tiles.example.com/{z}/{x}/{y}.png").unwrap()),
    )
    .unwrap();
    let mut layer = ImageryLayer::new(Some(Arc::new(provider)), ImageryLayerOptions::default());
    let imageries: Vec<_> = (0..22).map(|x| layer.get_imagery_from_cache(x, 0, 5, None)).collect();
    for imagery in &imageries {
        layer.request_imagery(imagery);
    }
    let snapshot = |imageries: &[Rc<RefCell<Imagery>>]| {
        json!({
            "states": imageries.iter().map(|i| state_name(i.borrow().state)).collect::<Vec<_>>(),
            "requestStates": imageries
                .iter()
                .map(|i| i.borrow().request.as_ref().map(|r| request_state_name(r.borrow().state)))
                .collect::<Vec<_>>(),
            "serverKey": imageries[0].borrow().request.as_ref().and_then(|r| r.borrow().options.server_key.clone()),
        })
    };
    let compare = |actual: Value, expected: &Value, stage: &str| {
        for key in ["states", "requestStates", "serverKey"] {
            assert_eq!(actual[key], expected[key], "{stage} {key}");
        }
    };
    compare(snapshot(&imageries), &expected["afterRequests"], "after requests");

    // Cancel two active requests; the scheduler acts on its next update.
    for index in [0, 3] {
        let request = imageries[index].borrow().request.clone().unwrap();
        request.borrow_mut().cancel();
    }
    client.scheduler.borrow_mut().poll_update(&mut std::task::Context::from_waker(std::task::Waker::noop()));
    for imagery in &imageries {
        layer.poll_imagery(imagery);
    }
    compare(snapshot(&imageries), &expected["afterCancel"], "after cancel");

    // The freed slots let the cancelled tiles start again first.
    for imagery in &imageries {
        if imagery.borrow().state == ImageryState::Unloaded {
            layer.request_imagery(imagery);
        }
    }
    compare(snapshot(&imageries), &expected["afterRetry"], "after retry");
}
